      "concern_id": "C46",
      "effect": "costs",
      "direction": null,
      "quote": "No county jail may hold a person beyond the time the person would otherwise be released solely on the basis of a detainer request from federal immigration authorities.",
      "mechanism": "Restricts the detention powers of county jails by removing their ability to hold individuals on administrative immigration detainers.",
      "certainty": "stated"
